function mergeIntervals(intervals) {
  // Sort starts and ends independently; a merged block closes when the
  // next start lies beyond the current end.
  const n = intervals.length;
  const starts = intervals.map((iv) => iv[0]).sort((a, b) => a - b);
  const ends = intervals.map((iv) => iv[1]).sort((a, b) => a - b);
  const out = [];
  let blockStart = starts[0];
  for (let i = 0; i < n; i++) {
    if (i === n - 1 || starts[i + 1] > ends[i]) {
      out.push([blockStart, ends[i]]);
      if (i < n - 1) blockStart = starts[i + 1];
    }
  }
  return out;
}

